UPDATE t_file_object
SET current_version_no=#{version.versionNo},object_version=#{version.objectVersion},content_hash=#{version.contentHash},
size_bytes=#{version.sizeBytes},mime_type=#{version.mimeType},storage_encryption_key_ref=#{version.storageEncryptionKeyRef},
scan_policy_id=#{version.scanPolicyId},scan_status='AVAILABLE',available_time=#{now},version=version+1,update_time=#{now}
WHERE file_id=#{version.fileId} AND current_version_no=#{currentVersionNo}
